using System.Collections.Generic;
using LittleLeo;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "BrightEnhancementAction", menuName = "Data/Battle/Battle Actions/Moonie/BrightEnhancement Action")]
public class BrightEnhancementAction : EnhanceAction
{
	[SerializeField]
	private PlayerDiceInventoryData allDicePool;

	[SerializeField]
	private float secondSFXDelay;

	protected override void EnhanceFirstAction(DiceInstance diceInstance)
	{
		Dice dice = diceInstance.OriginalDice.InstantiateScriptableObjectTryingToCopyDiceFacesModded();
		int finalValue = FinalValue(diceInstance);
		ModifyFirstAction(diceInstance, finalValue, dice);
		if (diceInstance.ActionFace.EnableSecondAction)
		{
			ChangeDieFace(diceInstance.ActionFace);
			ChangeDieFace(dice.GetDiceFaces()[diceInstance.RolledDiceFaceIndex]);
		}
		KeepChangedAndUpdateActionValueModifier(diceInstance, dice);
		static void ChangeDieFace(ActionFace actionFace)
		{
			actionFace.NewSecondBattleAction = actionFace.SecondBattleAction;
			actionFace.NewSecondActionValue = actionFace.SecondActionValue;
		}
	}

	protected override void EnhanceSecondAction(DiceInstance diceInstance)
	{
		Dice dice = diceInstance.OriginalDice.InstantiateScriptableObjectTryingToCopyDiceFacesModded();
		int finalValue = FinalValue(diceInstance);
		ModifySecondAction(diceInstance, finalValue, dice);
		ChangeDieFace(diceInstance.ActionFace);
		ChangeDieFace(dice.GetDiceFaces()[diceInstance.RolledDiceFaceIndex]);
		KeepChangedAndUpdateActionValueModifier(diceInstance, dice);
		static void ChangeDieFace(ActionFace actionFace)
		{
			actionFace.NewBattleAction = actionFace.BattleAction;
			actionFace.NewActionValue = actionFace.ActionValue;
		}
	}

	protected override void EnhanceBothActions(DiceInstance diceInstance)
	{
		Dice newOriginalDice = diceInstance.OriginalDice.InstantiateScriptableObjectTryingToCopyDiceFacesModded();
		int finalValue = FinalValue(diceInstance);
		ModifyFirstAction(diceInstance, finalValue, newOriginalDice);
		ModifySecondAction(diceInstance, finalValue, newOriginalDice);
		KeepChangedAndUpdateActionValueModifier(diceInstance, newOriginalDice);
	}

	private void ModifyFirstAction(DiceInstance diceInstance, int finalValue, Dice newOriginalDice)
	{
		ChangeDieFace(diceInstance.ActionFace);
		ChangeDieFace(newOriginalDice.GetDiceFaces()[diceInstance.RolledDiceFaceIndex]);
		void ChangeDieFace(ActionFace actionFace)
		{
			actionFace.BattleAction = diceInstance.ActionFace.BattleAction;
			actionFace.NewBattleAction = actionFace.BattleAction;
			actionFace.ActionValue = finalValue;
			actionFace.NewActionValue = finalValue;
		}
	}

	private void ModifySecondAction(DiceInstance diceInstance, int finalValue, Dice newOriginalDice)
	{
		ChangeDieFace(diceInstance.ActionFace);
		ChangeDieFace(newOriginalDice.GetDiceFaces()[diceInstance.RolledDiceFaceIndex]);
		void ChangeDieFace(ActionFace actionFace)
		{
			actionFace.SecondBattleAction = diceInstance.ActionFace.SecondBattleAction;
			actionFace.NewSecondBattleAction = actionFace.SecondBattleAction;
			actionFace.SecondActionValue = finalValue;
			actionFace.NewSecondActionValue = finalValue;
		}
	}

	private void KeepChangedAndUpdateActionValueModifier(DiceInstance diceInstance, Dice newOriginalDice)
	{
		diceInstance.ActionFace.KeepChanges = true;
		newOriginalDice.GetDiceFaces()[diceInstance.RolledDiceFaceIndex].KeepChanges = true;
		diceInstance.ActionFace.UpdateActionValueModifier();
		allDicePool.DiceForged(diceInstance, newOriginalDice);
	}

	protected override void PlaySecondSFXWithDelay(List<DiceInstance> diceList)
	{
		InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, secondSFXDelay, delegate
		{
			bool flag = false;
			for (int i = 0; i < diceList.Count; i++)
			{
				if (!diceList[i].Discarding && diceList[i].gameObject.activeInHierarchy)
				{
					flag = true;
					break;
				}
			}
			if (flag)
			{
				PlaySecondSFX();
			}
		});
	}
}
